{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Trametinib absolute oral bioavailability was 72.3% (range 45.7–92.8%) in patients with solid tumors, directly demonstrating that a complex, moderately lipophilic oral drug can achieve F well above 20% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "BI 425809 showed 71.64% absolute oral bioavailability in fasted humans, another high-F human example with a large lipophilic structure, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Nevirapine absolute oral bioavailability was 91 ± 8% in healthy volunteers, showing that orally administered drugs with substantial first-pass potential can still have high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Sunitinib absolute oral bioavailability is about 50% in fasted humans; its basic amine and aromatic heterocyclic features are relevant to the query's piperazine-hydrazone and naphthoquinone system, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Amphotericin B has negligible oral bioavailability due to poor permeability and solubility, but this low-F evidence is poorly transferable because the query is a less polar ansamycin, not a polyhydroxylated polyene macrolide.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is rifabutin, a rifamycin ansamycin. The supplied human absolute bioavailability evidence for relevant oral drugs is predominantly high (trametinib 72%, BI 425809 72%, nevirapine 91%, sunitinib 50%), and the only low-F evidence (amphotericin B) is structurally distant and poorly transferable. Rifabutin's reported oral bioavailability is approximately 20%, which meets the F≥20% threshold. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for rifabutin is included in the supplied evidence.",
    "The threshold is borderline if rifabutin F is exactly 20%.",
    "No rifamycin analogue with measured F is present in the evidence set.",
    "Amphotericin B low-F evidence is structurally distant from the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

